package com.nivor.search;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/search")public class SearchController{private final SearchService service;public SearchController(SearchService s){service=s;}@GetMapping public SearchDtos.SearchResponse search(@AuthenticationPrincipal UserDetails u,@RequestParam String q,@RequestParam(required=false)String type,@RequestParam(required=false)Integer limit){return service.search(u.getUsername(),q,type,limit);}}
